/// The convex hull of `points` (body frame, placed by `local`).
#[no_mangle]
pub unsafe extern "C" fn rbCreateHullShape(
    world: *mut RbWorld,
    body: RbBodyId,
    def: *const RbShapeDef,
    points: *const RbVec3,
    count: u32,
    local: RbTransform,
    out: *mut RbShapeId,
) -> RbResult {
    create_shape(world, body, def, out, |w| {
        if points.is_null() || count < 4 {
            return Err(invalid("a hull needs at least 4 points"));
        }
        let pts: Vec<glam::Vec3> = std::slice::from_raw_parts(points, count as usize)
            .iter()
            .map(|p| glam::Vec3::from(w.coords.position_in(p.a())))
            .collect();
        let hull = ConvexHull::from_points(&pts).map_err(|e| anyhow::anyhow!("hull: {e:?}"))?;
        Ok(Geometry::Hull {
            hull,
            transform: w.transform_in(local),
        })
    })
}

