unsafe fn create_joint(
    world: *mut RbWorld,
    out: *mut RbJointId,
    build: impl FnOnce(&RbWorld) -> anyhow::Result<JointDef>,
) -> RbResult {
    guard_args(|| {
        let w = world_mut(world)?;
        let def = build(w)?;
        let id = w.world.create_joint(&def)?;
        if matches!(def, JointDef::Prismatic(_) | JointDef::Distance(_)) {
            w.linear_joints.insert(id.to_bits());
        }
        write(out, id.to_bits())
    })
}

#[no_mangle]
pub unsafe extern "C" fn rbCreateRevoluteJoint(
    world: *mut RbWorld,
    def: *const RbRevoluteJointDef,
    out: *mut RbJointId,
) -> RbResult {
    create_joint(world, out, |w| {
        let d = read(def, "null joint def")?;
        check_cookie(
            d.internal_value,
            "joint def not from rbDefaultRevoluteJointDef",
        )?;
        let c = &w.coords;
        let (lo, hi) = (
            c.joint_angle_in(d.lower_angle),
            c.joint_angle_in(d.upper_angle),
        );
        Ok(JointDef::Revolute(RevoluteJointDef {
            base: w.joint_base(&d.base),
            target_angle: c.joint_angle_in(d.target_angle),
            spring: d.enable_spring.then(|| Spring {
                stiffness: c.torque_in(d.stiffness),
                damping: c.torque_in(d.damping),
            }),
            limit: d.enable_limit.then(|| (lo.min(hi), lo.max(hi))),
            motor: d.enable_motor.then(|| {
                (
                    c.joint_angle_in(d.motor_speed),
                    c.torque_in(d.max_motor_torque),
                )
            }),
        }))
    })
}

#[no_mangle]
pub unsafe extern "C" fn rbCreatePrismaticJoint(
    world: *mut RbWorld,
    def: *const RbPrismaticJointDef,
    out: *mut RbJointId,
) -> RbResult {
    create_joint(world, out, |w| {
        let d = read(def, "null joint def")?;
        check_cookie(
            d.internal_value,
            "joint def not from rbDefaultPrismaticJointDef",
        )?;
        let c = &w.coords;
        Ok(JointDef::Prismatic(PrismaticJointDef {
            base: w.joint_base(&d.base),
            target_translation: 0.0,
            spring: None,
            limit: d.enable_limit.then(|| {
                (
                    c.length_in(d.lower_translation),
                    c.length_in(d.upper_translation),
                )
            }),
            motor: d
                .enable_motor
                .then(|| (c.length_in(d.motor_speed), c.force_in(d.max_motor_force))),
        }))
    })
}

#[no_mangle]
pub unsafe extern "C" fn rbCreateSphericalJoint(
    world: *mut RbWorld,
    def: *const RbSphericalJointDef,
    out: *mut RbJointId,
) -> RbResult {
    create_joint(world, out, |w| {
        let d = read(def, "null joint def")?;
        check_cookie(
            d.internal_value,
            "joint def not from rbDefaultSphericalJointDef",
        )?;
        let c = &w.coords;
        let (lo, hi) = (
            c.joint_angle_in(d.lower_twist_angle),
            c.joint_angle_in(d.upper_twist_angle),
        );
        Ok(JointDef::Spherical(SphericalJointDef {
            base: w.joint_base(&d.base),
            cone_angle: d.enable_cone_limit.then_some(d.cone_angle),
            twist_limit: d.enable_twist_limit.then(|| (lo.min(hi), lo.max(hi))),
        }))
    })
}

#[no_mangle]
pub unsafe extern "C" fn rbCreateWeldJoint(
    world: *mut RbWorld,
    def: *const RbWeldJointDef,
    out: *mut RbJointId,
) -> RbResult {
    create_joint(world, out, |w| {
        let d = read(def, "null joint def")?;
        check_cookie(d.internal_value, "joint def not from rbDefaultWeldJointDef")?;
        let c = &w.coords;
        Ok(JointDef::Weld(WeldJointDef {
            base: w.joint_base(&d.base),
            // N/m carries no net length unit (kg/s²): unchanged in cm.
            linear_stiffness: (d.linear_stiffness > 0.0).then_some(d.linear_stiffness),
            angular_stiffness: (d.angular_stiffness > 0.0)
                .then(|| c.torque_in(d.angular_stiffness)),
            plastic: (d.yield_torque > 0.0).then(|| Plastic {
                yield_torque: c.torque_in(d.yield_torque),
                break_bend: if d.break_bend > 0.0 {
                    d.break_bend
                } else {
                    f32::INFINITY
                },
            }),
        }))
    })
}

#[no_mangle]
pub unsafe extern "C" fn rbCreateDistanceJoint(
    world: *mut RbWorld,
    def: *const RbDistanceJointDef,
    out: *mut RbJointId,
) -> RbResult {
    create_joint(world, out, |w| {
        let d = read(def, "null joint def")?;
        check_cookie(
            d.internal_value,
            "joint def not from rbDefaultDistanceJointDef",
        )?;
        let c = &w.coords;
        Ok(JointDef::Distance(DistanceJointDef {
            base: w.joint_base(&d.base),
            length: c.length_in(d.length),
            spring: d.enable_spring.then_some(d.stiffness),
            limit: d
                .enable_limit
                .then(|| (c.length_in(d.min_length), c.length_in(d.max_length))),
        }))
    })
}

