// ----- vehicles and soft bodies ---------------------------------------------

/// A vehicle from a named preset ("sedan", "destructible_sedan", "kart",
/// "monster_truck", "dune_buggy", ...) at a chassis pose.
#[no_mangle]
pub unsafe extern "C" fn rbCreateVehiclePreset(
    world: *mut RbWorld,
    name: *const c_char,
    transform: RbTransform,
    out: *mut RbVehicleId,
) -> RbResult {
    guard_args(|| {
        let w = world_mut(world)?;
        if name.is_null() {
            return Err(invalid("null preset name"));
        }
        let name = CStr::from_ptr(name).to_string_lossy();
        let desc = engine_vehicle::presets::by_name(&name)
            .ok_or_else(|| anyhow::anyhow!("no vehicle preset {name:?}"))?;
        let t = w.transform_in(transform);
        let h = w.world.add_vehicle(&desc, t.position, t.rotation)?;
        write(out, h.0)
    })
}

#[no_mangle]
pub unsafe extern "C" fn rbVehicle_SetInput(
    world: *mut RbWorld,
    vehicle: RbVehicleId,
    input: RbVehicleInput,
) -> RbResult {
    guard_args(|| {
        let w = world_mut(world)?;
        w.world
            .set_vehicle_input(VehicleHandle(vehicle), vehicle_input(input));
        Ok(())
    })
}

/// Steering is semantic (positive steers right in every convention).
fn vehicle_input(input: RbVehicleInput) -> VehicleInput {
    VehicleInput {
        forward: input.forward,
        steer: input.steer,
        brake: input.brake,
        handbrake: input.handbrake,
        gear: if input.manual_gear {
            engine_vehicle::GearRequest::Gear(input.gear)
        } else {
            engine_vehicle::GearRequest::Auto
        },
    }
}

/// A soft-body vehicle from Rigs of Rods `.truck` text (the world needs
/// `enable_soft_bodies` and `RB_CONTACTS_CANONICAL`).
#[no_mangle]
pub unsafe extern "C" fn rbCreateSoftVehicleTruck(
    world: *mut RbWorld,
    truck: *const c_char,
    transform: RbTransform,
    out: *mut RbSoftId,
) -> RbResult {
    guard_args(|| {
        let w = world_mut(world)?;
        if truck.is_null() {
            return Err(invalid("null truck text"));
        }
        let text = CStr::from_ptr(truck).to_string_lossy();
        let desc = engine_softbody::truck::load_truck(&text);
        let t = w.transform_in(transform);
        let h =
            w.world
                .add_soft_vehicle(&desc, t.position, t.rotation, &SpawnOptions::default())?;
        write(out, h.0)
    })
}

