/// How a destructible's bonds fail (`StrengthModel`).
#[repr(C)]
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum RbStrengthModel {
    /// Breakable bond joints; every chunk is a body (the fracture lab's D6 mode).
    RB_STRENGTH_BONDS = 0,
    /// The fracture lab's GPU threshold splitter: bonded clusters are bodies that
    /// split on the GPU (its `threshold` mode). Projectiles: `rbBody_SetProjectile`.
    RB_STRENGTH_THRESHOLD = 1,
}

/// A placed destructible (`rbDefaultDestructibleDef`). Assets are authored in
/// Rubble's frame (Y up, metres); `transform` places them in the world's.
#[repr(C)]
#[derive(Clone, Copy, Debug)]
pub struct RbDestructibleDef {
    pub asset: RbDestructibleAssetId,
    pub transform: RbTransform,
    pub strength_scale: f32,
    /// Keep the asset's world bonds (anchors).
    pub anchored: bool,
    pub start_asleep: bool,
    pub friction: f32,
    pub user_data: u64,
    pub model: RbStrengthModel,
    /// `RB_STRENGTH_THRESHOLD` only: support loss. Each anchored piece's weight flows down its
    /// intact bonds, and a bond carrying more than its compressive capacity breaks, so a
    /// structure whose supports are shot away collapses. Off by default.
    pub support_loss: bool,
    /// With `support_loss`: the dynamic factor k, 1 to 2, on the increase of load after a
    /// sudden loss of support (a bond is held to before + k (after - before)). 1 (the
    /// default): quasi-static.
    pub support_loss_dynamic_factor: f32,
    pub internal_value: u32,
}

#[no_mangle]
pub extern "C" fn rbDefaultDestructibleDef() -> RbDestructibleDef {
    RbDestructibleDef {
        asset: 0,
        transform: RbTransform::default(),
        strength_scale: 1.0,
        anchored: true,
        start_asleep: true,
        friction: SurfaceMaterial::default().friction,
        user_data: 0,
        model: RbStrengthModel::RB_STRENGTH_BONDS,
        support_loss: false,
        support_loss_dynamic_factor: 1.0,
        internal_value: COOKIE,
    }
}

#[no_mangle]
pub unsafe extern "C" fn rbCreateDestructible(
    world: *mut RbWorld,
    def: *const RbDestructibleDef,
    out: *mut RbDestructibleId,
) -> RbResult {
    guard_args(|| {
        let w = world_mut(world)?;
        let d = read(def, "null destructible def")?;
        check_cookie(
            d.internal_value,
            "destructible def not from rbDefaultDestructibleDef",
        )?;
        let base = DestructibleDef::new(DestructibleAssetId(d.asset));
        let def = DestructibleDef {
            transform: w.transform_in(d.transform),
            strength_scale: d.strength_scale,
            anchors: if d.anchored {
                Anchors::AssetWorldBonds
            } else {
                Anchors::None
            },
            asleep: d.start_asleep,
            shape: ShapeDef {
                material: SurfaceMaterial {
                    friction: d.friction,
                    ..SurfaceMaterial::default()
                },
                ..base.shape.clone()
            },
            user_data: d.user_data,
            model: strength_model(d.model),
            support_loss: d.support_loss,
            support_loss_dynamic_factor: d.support_loss_dynamic_factor,
            ..base
        };
        let id = w.world.create_destructible(&def)?;
        write(out, id.to_bits())
    })
}

fn strength_model(m: RbStrengthModel) -> StrengthModel {
    match m {
        RbStrengthModel::RB_STRENGTH_BONDS => StrengthModel::Bonds,
        RbStrengthModel::RB_STRENGTH_THRESHOLD => StrengthModel::Threshold,
    }
}

